import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

const r2 = new S3Client({
  region: 'auto',
  endpoint: `https://{{account_id}}.r2.cloudflarestorage.com`,
  credentials: {
    accessKeyId: '{{access_key_id}}',
    secretAccessKey: '{{secret_access_key}}',
  },
});

export async function putToR2(key: string, body: Buffer, contentType: string) {
  await r2.send(new PutObjectCommand({
    Bucket: '{{bucket_name}}',
    Key: key,
    Body: body,
    ContentType: contentType,
  }));
}

export async function r2PresignedPut(key: string, contentType: string) {
  const cmd = new PutObjectCommand({ Bucket: '{{bucket_name}}', Key: key, ContentType: contentType });
  return await getSignedUrl(r2, cmd, { expiresIn: 600 });
}
